import json, os

questions = []

def add_q(chapter_id, subject_id, topic, question, options, correct_idx, explanation, difficulty="easy", category="basic"):
    idx = len(questions) + 1
    questions.append({
        "id": f"mcq-c6-{len(questions)+1:03d}",
        "chapterId": chapter_id,
        "subjectId": subject_id,
        "classId": "class-6",
        "topic": topic,
        "question": question,
        "options": options,
        "correctAnswerIndex": correct_idx,
        "explanation": explanation,
        "difficulty": difficulty,
        "category": category
    })

